<header class="admin-header"><div><p class="eyebrow">Content</p><h1>Posts</h1></div><a class="button" href="<?= e(url('admin/posts/create')) ?>">New post</a></header><section class="panel"><div class="table-wrap"><table><thead><tr><th>Title</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><a href="<?= e(url('admin/posts/'.$item['id'].'/edit')) ?>"><?= e($item['title']) ?></a></td><td><span class="badge"><?= e($item['status']) ?></span></td><td><?= e($item['updated_at']) ?></td><td><form method="post" action="<?= e(url('admin/posts/'.$item['id'].'/delete')) ?>" data-confirm="Delete this post?"><?= csrf_field() ?><button class="link danger">Delete</button></form></td></tr><?php endforeach?></tbody></table></div></section>
